package dev.setugarg.supportagent.tools;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import dev.setugarg.supportagent.llm.Llm;

import java.time.Clock;
import java.time.LocalDate;
import java.util.Map;

/**
 * A capability the model can invoke. The model only ever sees {@link #spec()}; the
 * implementation runs in our process with our permissions.
 *
 * <p>Golden rule: <b>the LLM proposes, code disposes</b>. Every tool re-validates its input and
 * enforces authorization and business rules itself, because tool arguments are generated by a
 * model that can be confused or prompt-injected.
 */
public interface AgentTool {

    ObjectMapper JSON = new ObjectMapper();

    Llm.ToolSpec spec();

    Result execute(JsonNode input, Context ctx);

    /** Who is asking. Comes from the authenticated session, never from the model. */
    record Context(String customerEmail, String sessionId, Clock clock) {
        public LocalDate today() {
            return LocalDate.now(clock);
        }
    }

    /** {@code content} is what the model sees; {@code isError} tells it the call failed. */
    record Result(String content, boolean isError) {
        public static Result ok(Object payload) {
            try {
                return new Result(JSON.writeValueAsString(payload), false);
            } catch (Exception e) {
                return new Result(String.valueOf(payload), false);
            }
        }

        public static Result error(String message) {
            return new Result("{\"error\":\"" + message.replace("\"", "'") + "\"}", true);
        }
    }

    static Map<String, Object> schema(Map<String, Object> properties, String... required) {
        return Map.of("type", "object", "properties", properties, "required", java.util.List.of(required));
    }

    static String requireText(JsonNode input, String field) {
        JsonNode v = input == null ? null : input.get(field);
        if (v == null || !v.isTextual() || v.asText().isBlank()) {
            throw new IllegalArgumentException("missing required field '" + field + "'");
        }
        return v.asText().trim();
    }
}
